import test from 'node:test';
import assert from 'node:assert/strict';
import { equations as e } from '../src/index.mjs';
import { near } from './helpers.mjs';
test('single-phase current uses electrical input and PF', () => near(assert, e.electricalCurrent({ powerW: 4600, voltageV: 230, powerFactor: .8, phases: 1 }), 25));
test('balanced three-phase current uses line voltage', () => near(assert, e.electricalCurrent({ powerW: Math.sqrt(3) * 400 * 10 * .8, voltageV: 400, powerFactor: .8, phases: 3 }), 10));
test('zero PF and unspecified phase count are rejected', () => { assert.throws(() => e.electricalCurrent({ powerW: 1, voltageV: 230, powerFactor: 0, phases: 1 })); assert.throws(() => e.electricalCurrent({ powerW: 1, voltageV: 230, powerFactor: 1, phases: 2 })); });
test('single-phase voltage drop uses one-way metres converted to kilometres', () => { const r = e.voltageDrop({ currentA: 10, lengthM: 100, resistanceOhmPerKm: 1, reactanceOhmPerKm: 0, powerFactor: 1, phases: 1, voltageV: 230 }); near(assert, r.volts, 2); near(assert, r.percent, 200 / 230); });
test('voltage drop includes reactive impedance and three-phase factor', () => near(assert, e.voltageDrop({ currentA: 10, lengthM: 100, resistanceOhmPerKm: 2, reactanceOhmPerKm: .5, powerFactor: .8, phases: 3, voltageV: 400 }).volts, Math.sqrt(3) * 1.9));
test('lumen-method fixture count rounds upward', () => { assert.equal(e.lightingCount({ targetLux: 300, areaM2: 20, lumensPerFixture: 1000, utilizationFactor: .5, maintenanceFactor: .8 }), 15); assert.equal(e.lightingCount({ targetLux: 301, areaM2: 20, lumensPerFixture: 1000, utilizationFactor: .5, maintenanceFactor: .8 }), 16); });
test('maintenance factor cannot be zero or greater than one', () => { for (const maintenanceFactor of [0, 1.1]) assert.throws(() => e.lightingCount({ targetLux: 300, areaM2: 20, lumensPerFixture: 1000, utilizationFactor: .5, maintenanceFactor })); });
test('electrical P/Q and demand components preserve units', () => { const p = e.powerComponents({ powerW: 800, powerFactor: .8, demandFactor: .5 }); near(assert, p.connectedVar, 600); near(assert, p.demandW, 400); near(assert, p.demandVar, 300); });
const thermal = { outdoorC: 44, indoorC: 24, surfaces: [{ areaM2: 10, uWm2K: .5 }], solarW: 100, internalSensibleW: 200, internalLatentW: 50, infiltrationM3S: .005, outdoorAirM3S: .005, outdoorHumidityRatio: .01, indoorHumidityRatio: .008, densityKgM3: 1.2, cpJkgK: 1000, latentHeatJkg: 2500000 };
test('static sensible and latent components match independently computed balance', () => { const q = e.steadyStateHeatGain(thermal); near(assert, q.conductionW, 100); near(assert, q.airSensibleW, 240); near(assert, q.sensibleW, 640); near(assert, q.latentW, 110); near(assert, q.totalW, 750); });
test('absent humidity is not silently treated as zero', () => { const p = { ...thermal }; delete p.outdoorHumidityRatio; assert.throws(() => e.steadyStateHeatGain(p)); });
test('cooling-gain function does not invent negative cooling in cold weather', () => { const q = e.steadyStateHeatGain({ ...thermal, outdoorC: 10 }); assert.equal(q.conductionW, 0); assert.equal(q.airSensibleW, 0); });
test('sensible airflow uses positive supply temperature difference', () => { near(assert, e.sensibleAirflow({ sensibleW: 640, densityKgM3: 1.2, cpJkgK: 1000, supplyDeltaK: 10 }), 640 / 12000); assert.throws(() => e.sensibleAirflow({ sensibleW: 640, densityKgM3: 1.2, cpJkgK: 1000, supplyDeltaK: 0 })); });
test('supplied zone ventilation rates convert L/s to m3/s', () => near(assert, e.zoneOutdoorAir({ persons: 3, areaM2: 20, lSPerPerson: 2, lSPerM2: .3, distributionEffectiveness: 1 }), .012));
test('ACH conversion uses seconds per hour', () => near(assert, e.achAirflow({ volumeM3: 100, airChangesPerHour: 6 }), 1 / 6));
test('circular area diameter is a physical diameter, not a nominal pipe size', () => near(assert, e.circularDiameter({ flowM3S: Math.PI * .1 ** 2 / 4 * .5, velocityMS: .5 }), .1));
test('drain fall and tank volume use explicit design inputs', () => { near(assert, e.drainageFall({ horizontalLengthM: 10, slope: .02 }), .2); assert.equal(e.tankVolume({ persons: 5, litresPerPersonDay: 200, autonomyDays: 2 }), 2000); });
test('rain conversion from mm/hour to cubic metres/second', () => near(assert, e.rainfallFlow({ intensityMmH: 90, areaM2: 100, runoffCoefficient: 1 }), .0025));
test('water heating distinguishes thermal output and electrical input', () => near(assert, e.waterHeatingPower({ flowM3S: .001, deltaK: 10, densityKgM3: 1000, cpJkgK: 4200, efficiency: .9 }), 42000 / .9));
test('Darcy head includes elevation, residual, friction and fittings', () => { const p = e.hydraulicHead({ flowM3S: Math.PI * .1 ** 2 / 4, diameterM: .1, lengthM: 100, darcyFrictionFactor: .02, minorLossK: 2, elevationRiseM: 5, requiredResidualHeadM: 10, gravityMS2: 10 }); near(assert, p.velocityMS, 1); near(assert, p.totalHeadM, 16.1); });
test('nonfinite and negative physical quantities fail', () => { assert.throws(() => e.circularDiameter({ flowM3S: -1, velocityMS: 1 })); assert.throws(() => e.achAirflow({ volumeM3: Infinity, airChangesPerHour: 6 })); });
